using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Abstractions.Persistence.Specifications;using OAS.Application.Accounting.Abstractions;using OAS.Application.Common.Exceptions;using OAS.Contracts.Accounting.PaymentVouchers;using OAS.Domain.Accounting.Entities;using DomainPartyType=OAS.Domain.Accounting.Enums.SettlementPartyType;using DomainPaymentMethod=OAS.Domain.Accounting.Enums.PaymentMethod;using DomainRateType=OAS.Domain.Accounting.Enums.ExchangeRateType;
namespace OAS.Application.Accounting.PaymentVouchers.Commands.UpdatePaymentVoucher;
public sealed class UpdatePaymentVoucherCommandHandler(IRepository<PaymentVoucher,Guid> repository,IRepository<PaymentVoucherLine,Guid> lineRepository,IVoucherSettlementResolver settlements,IReadRepository<AccountingSettings,Guid> settingsRepository,IReadRepository<Currency,Guid> currencies):IRequestHandler<UpdatePaymentVoucherCommand>
{
 public async Task Handle(UpdatePaymentVoucherCommand request,CancellationToken ct){var voucher=await repository.GetForUpdateAsync(request.Id,ct)??throw new NotFoundException(nameof(PaymentVoucher),request.Id);byte[] rv;try{rv=Convert.FromBase64String(request.Data.RowVersion);}catch(FormatException ex){throw new ConcurrencyException("Payment voucher row version is invalid.",ex);}if(!voucher.RowVersion.SequenceEqual(rv))throw new ConcurrencyException("The payment voucher has been modified by another user.");var settings=await settingsRepository.GetByIdAsync(AccountingSettings.SingletonId,ct)??throw new ConflictException("accounting_settings_required","Accounting settings and base currency must be configured first.");var baseCurrency=await currencies.GetByIdAsync(settings.BaseCurrencyId,ct)??throw new ConflictException("base_currency_missing","Configured base currency does not exist.");var resolved=new List<(CreatePaymentVoucherLineRequest Request,VoucherSettlementResolution Value)>();foreach(var line in request.Data.Lines){var x=await settlements.ResolveAsync(request.Data.VoucherDate,(DomainPartyType)(byte)line.PartyType,line.CustomerId,line.SupplierId,line.EmployeeId,line.PartyName,line.CounterpartyAccountId,(DomainPaymentMethod)(byte)line.PaymentMethod,line.CashAccountId,line.BankAccountId,line.SettlementAccountId,line.CurrencyId,line.Amount,line.ExchangeRate,(DomainRateType)(byte)line.ExchangeRateType,line.ReferenceNumber,ct);resolved.Add((line,x));}var total=resolved.Sum(x=>x.Value.BaseAmount);if(total<=0)throw new ConflictException("payment_voucher_total_invalid","Payment voucher must have a positive base total.");voucher.UpdateSettlementDocument(request.Data.VoucherDate,baseCurrency.Id,baseCurrency.Code,baseCurrency.DecimalPlaces,total,request.Data.Description);var existing=await lineRepository.ListAsync(new Specification<PaymentVoucherLine>().Where(x=>x.PaymentVoucherId==voucher.Id).Tracking(),ct);if(existing.Count>0)lineRepository.DeleteRange(existing);var n=1;var lines=resolved.Select(item=>{var r=item.Request;var x=item.Value;return PaymentVoucherLine.CreateSettlement(Guid.NewGuid(),voucher.Id,n++,x.PartyType,x.CustomerId,x.SupplierId,x.EmployeeId,x.PartyNameSnapshot,x.CounterpartyAccountId,x.PaymentMethod,x.CashAccountId,x.BankAccountId,x.SettlementAccountId,x.CurrencyId,x.CurrencyCode,x.CurrencySymbol,x.CurrencyDecimalPlaces,x.Amount,x.ExchangeRate,x.ExchangeRateDate,x.ExchangeRateType,x.ExchangeRateSource,x.BaseAmount,r.ReferenceNumber,r.ReferenceDate,r.ReferenceType,r.ReferenceId,r.Description);}).ToList();voucher.ReplaceLines(lines);if(lines.Count>0)await lineRepository.AddRangeAsync(lines,ct);repository.Update(voucher);}
}
